insert into public.settings (id, data) values (1, $j${"company":{"name":"Draco Graphix","vat_number":"02314280682","email":"info@dracographix.com","phone":"+39 351 8293757","instagram":"@dracographix","facebook":"facebook.com/dracographix","address":""},"deposit_cents":5000,"vat_percent":22,"shipping_flat_cents":900,"shipping_free_over_cents":null,"lead_time":"In media 3–5 giorni per produzione e spedizione, secondo il carico di lavoro.","payment_methods":[{"id":"bonifico","label":"Bonifico bancario","instructions":"Dopo l’ordine ti mostriamo i dati per il bonifico. Appena arriva il pagamento passiamo alla lavorazione.","enabled":true},{"id":"paypal","label":"PayPal","instructions":"Ti indichiamo il link per pagare con PayPal. Appena riceviamo il pagamento passiamo alla lavorazione.","enabled":true},{"id":"carta","label":"Carta di credito","instructions":"Pagamento online con carta.","enabled":false}],"couriers":["BRT","GLS","SDA","Poste Italiane","DHL","UPS","Altro"],"privacy_text":"BOZZA da far verificare prima della pubblicazione.\n\nTitolare del trattamento: Draco Graphix, P.IVA 02314280682, info@dracographix.com.\n\nDati che raccogliamo: nome, email, telefono, indirizzi di spedizione e dati di fatturazione che inserisci per ordinare; moto, grafiche e file che carichi; messaggi che ci scrivi.\nA cosa servono: gestire ordini, progetti e preventivi, spedire, fatturare, risponderti. Se lo scegli, inviarti novità (newsletter).\nPer quanto li conserviamo: per il tempo necessario a eseguire il contratto e agli obblighi fiscali.\nI tuoi diritti: accesso, rettifica, cancellazione, opposizione e portabilità, scrivendo a info@dracographix.com.\nCookie: l’app usa solo memoria tecnica del browser (accesso, carrello, tema chiaro/scuro).","terms_text":"BOZZA da far verificare prima della pubblicazione.\n\nKit semi-personalizzati: realizzati su ordinazione per il modello e l’annata indicati.\nGrafiche personalizzate: acconto alla richiesta; la bozza si può modificare fino all’approvazione; il saldo si versa dopo l’approvazione; l’acconto viene scalato dal totale.\nTempi: in media 3–5 giorni per produzione e spedizione, secondo il carico di lavoro.\nRecesso e garanzia: prodotti su misura, vedi la normativa sul diritto di recesso per beni personalizzati."}$j$::jsonb) on conflict (id) do nothing;
